export function mountTakeLanes({root,track,project,engine,assets,toast,updateTransport,esc}){
 const section=document.createElement('section');section.className='take-lanes';section.innerHTML=`<div class="take-lane-title"><strong>PRISES · ÉCOUTER ET SÉLECTIONNER</strong><button id="takeAuditionStop" class="outline-btn">Stop</button></div><p>Glisse sur une prise alternative pour choisir la plage à assembler. L’écoute garde les autres pistes du morceau.</p>${track.playlists.map(l=>`<div class="take-lane-row ${l.id===track.activePlaylist?'active':''}"><div><strong>${esc(l.name)}</strong><small>${l.id===track.activePlaylist?'ACTIVE':'ALTERNATIVE'}</small><button class="outline-btn" data-listen-take="${l.id}" aria-label="Écouter la prise ${esc(l.name)}">▶ Écouter</button></div><div class="take-lane-wave" data-take-lane="${l.id}" aria-label="Sélectionner une plage de ${esc(l.name)}">${l.clips.map(c=>`<span class="take-audio-clip" style="left:${c.start/project.bars*100}%;width:${c.length/project.bars*100}%"><svg viewBox="0 0 120 36" preserveAspectRatio="none"><polyline points="${wave(assets.get(c.audioId)?.buffer,c,project.bpm)}"/></svg></span>`).join('')}<span class="take-range" hidden></span></div></div>`).join('')}<output id="takeRangeStatus">Sélectionne une prise source ci-dessous ou une plage sur son onde.</output>`;
 root.prepend(section);const stop=()=>{engine.pause();engine.takePreview=null;updateTransport();};
 section.querySelector('#takeAuditionStop').onclick=stop;for(const b of section.querySelectorAll('[data-listen-take]'))b.onclick=async()=>{try{stop();engine.patternMode=null;engine.clipPreview=null;engine.takePreview={trackId:track.id,clips:track.playlists.find(l=>l.id===b.dataset.listenTake).clips};engine.position=Math.max(0,(Number(document.getElementById('compStart').value)-1)*16);await engine.play();updateTransport();}catch(error){toast(error.message);}};
 for(const lane of section.querySelectorAll('[data-take-lane]')){let start=null;const position=e=>Math.max(0,Math.min(project.bars,(e.clientX-lane.getBoundingClientRect().left)/lane.clientWidth*project.bars)),update=end=>{const from=Math.round(Math.min(start,end)*16)/16,to=Math.min(project.bars,Math.max(from+1/16,Math.round(Math.max(start,end)*16)/16)),range=lane.querySelector('.take-range');document.getElementById('compSource').value=lane.dataset.takeLane;document.getElementById('compStart').value=(from+1).toFixed(3);document.getElementById('compEnd').value=(to+1).toFixed(3);section.querySelectorAll('.take-range').forEach(el=>el.hidden=true);range.hidden=false;range.style.left=from/project.bars*100+'%';range.style.width=(to-from)/project.bars*100+'%';section.querySelector('#takeRangeStatus').textContent='Plage : mesure '+(from+1).toFixed(2)+' → '+(to+1).toFixed(2);};
  lane.onpointerdown=e=>{if(lane.dataset.takeLane===track.activePlaylist){toast('Sélectionne une prise alternative pour le comping.');return;}start=position(e);lane.setPointerCapture(e.pointerId);update(start+.25);e.preventDefault();};lane.onpointermove=e=>{if(start!==null)update(position(e));};lane.onpointerup=()=>start=null;lane.onpointercancel=()=>start=null;
 }
 document.getElementById('modal').addEventListener('close',stop,{once:true});
}
function wave(buffer,clip,bpm){if(!buffer)return '';const d=buffer.getChannelData(0),offset=Math.floor((clip.sourceOffset||0)*buffer.sampleRate),length=Math.min(d.length-offset,clip.length*240/bpm*buffer.sampleRate),points=[];for(let i=0;i<120;i++){let peak=0;for(let j=0;j<8;j++){const at=offset+Math.floor((i+j/8)/120*length);peak=Math.max(peak,Math.abs(d[at]||0));}points.push(`${i},${18-peak*17}`,`${i},${18+peak*17}`);}return points.join(' ');}
